Payload_Object.inputs:
@json(
  substring(
    replace(
      string(body('Payload_Array')),
      '},{',
      ','
    ), 
    1, 
    sub(
      length(
        replace(
          string(body('Payload_Array')),
          '},{',
          ','
        )
      ), 
      2
    )
  )
)

User Message:
@if(
  contains(
    body('Get_Doc_Content')?['$content-type'],
    'image'
  ),
  addProperty(
    json('{"type": "input_image"}'),
    'image_url',
    concat(
      'data:', body('Get_Doc_Content')?['$content-type'],
      ';base64,', base64(body('Get_Doc_Content'))
    )
  ),
  addProperty(
    addProperty(
      json('{"type": "input_file"}'),
      'file_data',
      concat(
        'data:', body('Get_Doc_Content')?['$content-type'],
        ';base64,', base64(body('Get_Doc_Content'))
      )
    ),
    'filename',
    items('Each_Document')?['name']
  )
)

