Document_Name.inputs:
@if(
  contains(
    items('Each_Document')?['name'],
    '.'
  ),
  items('Each_Document')?['name'],
  concat(
    items('Each_Document')?['name'],
    items('Each_Document')?['fileType']
  )
)

inputs.where:
@equals(and(
  or(
    contains(
      toLower(item()?['name']),
      'amendment'
    ),
    contains(
      toLower(item()?['name']),
      'assistance'
    ),
    contains(
      toLower(item()?['name']),
      'dha'
    ),
    contains(
      toLower(item()?['name']),
      'hap'
    ),
    contains(
      toLower(item()?['name']),
      'housing'
    ),
    contains(
      toLower(item()?['name']),
      'invoice'
    ),
    contains(
      toLower(item()?['name']),
      'program agreement'
    ),
    contains(
      toLower(item()?['name']),
      'rfta'
    ),
    contains(
      toLower(item()?['name']),
      'welcome packet'
    ),
    contains(
      toLower(item()?['path']),
      'welcome letter'
    ),
    and(
      or(
        contains(
          toLower(item()?['name']),
          'the ashley'
        ),
        contains(
          toLower(item()?['name']),
          'the ace'
        ),
        contains(
          toLower(item()?['name']),
          'the milo'
        )
      ),
      contains(
        toLower(item()?['name']),
        toLower(triggerBody()?['text_4'])
      )
    )
  ),
  greaterOrEquals(
    formatDateTime(
      item()?['dateAttached'],
      'yyyy-MM-dd'
    ),
    addDays(
      triggerBody()?['text_5'],
      -31,
      'yyyy-MM-dd'
    )
  ),
  and(
    not(
      contains(
        body('Resident_Filenames'),
        item()?['name']
      )
    ),
    not(
      contains(
        body('Resident_Filenames'),
        concat(
          item()?['name'],
          item()?['fileType']
        )
      )
    )
  )
),true)
